class OutputProcessor extends AudioWorkletProcessor {
    constructor() {
        super();
        this.audioQueue = [];
        this.currentBuffer = null;
        this.currentIndex = 0;
        this.isPlaying = false;
        this.isPaused = false;
        
        this.port.onmessage = (event) => {
            if (event.data.type === 'audioData') {
                if (!this.isPaused) {
                    this.audioQueue.push(event.data.data);
                }
            } else if (event.data.type === 'pause') {
                this.isPaused = true;
                this.clearQueue();
            } else if (event.data.type === 'resume') {
                this.isPaused = false;
            } else if (event.data.type === 'clear') {
                this.clearQueue();
            }
        };
    }
    
    clearQueue() {
        this.audioQueue = [];
        this.currentBuffer = null;
        this.currentIndex = 0;
        if (this.isPlaying) {
            this.isPlaying = false;
            this.port.postMessage({ type: 'stopSpeaking' });
        }
    }

    process(inputs, outputs, parameters) {
        const output = outputs[0];
        if (output.length > 0) {
            const channelData = output[0];
            
            for (let i = 0; i < channelData.length; i++) {
                if (this.isPaused) {
                    channelData[i] = 0;
                    continue;
                }
                
                if (!this.currentBuffer || this.currentIndex >= this.currentBuffer.length) {
                    if (this.audioQueue.length > 0) {
                        this.currentBuffer = this.audioQueue.shift();
                        this.currentIndex = 0;
                        
                        if (!this.isPlaying) {
                            this.isPlaying = true;
                            this.port.postMessage({ type: 'startSpeaking' });
                        }
                    } else {
                        channelData[i] = 0;
                        if (this.isPlaying) {
                            this.isPlaying = false;
                            this.port.postMessage({ type: 'stopSpeaking' });
                        }
                        continue;
                    }
                }
                
                channelData[i] = this.currentBuffer[this.currentIndex++];
            }
        }
        return true;
    }
}
